def split_words(text: str) -> list[str]:
    words: list[str] = []
    current: list[str] = []
    in_word = False
    length = len(text)
    index = 0
    separators = " \t\n"
    double_quote_escapes = '"\\$`'

    while index < length:
        char = text[index]

        if char in separators:
            if in_word:
                words.append("".join(current))
                current = []
                in_word = False
            index += 1
        elif char == "#" and not in_word:
            newline_index = text.find("\n", index)
            if newline_index == -1:
                index = length
            else:
                index = newline_index
        elif char == "'":
            close_index = text.find("'", index + 1)
            if close_index == -1:
                raise ValueError("unterminated single quote")
            current.append(text[index + 1:close_index])
            in_word = True
            index = close_index + 1
        elif char == '"':
            index += 1
            closed = False
            while index < length:
                inner = text[index]
                if inner == '"':
                    closed = True
                    index += 1
                    break
                if inner == "\\":
                    if index + 1 >= length:
                        raise ValueError("unterminated double quote")
                    following = text[index + 1]
                    if following in double_quote_escapes:
                        current.append(following)
                        index += 2
                    elif following == "\n":
                        index += 2
                    else:
                        current.append("\\")
                        index += 1
                else:
                    current.append(inner)
                    index += 1
            if not closed:
                raise ValueError("unterminated double quote")
            in_word = True
        elif char == "\\":
            if index + 1 >= length:
                raise ValueError("trailing backslash")
            following = text[index + 1]
            if following == "\n":
                index += 2
            else:
                current.append(following)
                in_word = True
                index += 2
        else:
            current.append(char)
            in_word = True
            index += 1

    if in_word:
        words.append("".join(current))
    return words
